alter table snowlog_import.progress_history alter column id set default gen_random_uuid();
alter table snowlog_import.progress_history alter column recorded_at set default now();
alter table snowlog_import.progress_history alter column baseline set default false;
alter table snowlog_import.resources alter column id set default gen_random_uuid();
alter table snowlog_import.resources alter column url set default ''::text;
alter table snowlog_import.resources alter column notes set default ''::text;
alter table snowlog_import.resources alter column skill_id set default ''::text;
alter table snowlog_import.resources alter column updated_at set default now();
alter table snowlog_import.profiles alter column stance set default '未確定'::text;
alter table snowlog_import.profiles alter column goal set default ''::text;
alter table snowlog_import.profiles alter column focus_skills set default '{}'::text[];
alter table snowlog_import.progress alter column id set default gen_random_uuid();
alter table snowlog_import.progress alter column status set default 0;
alter table snowlog_import.progress alter column conditions set default ''::text;
alter table snowlog_import.progress alter column notes set default ''::text;
alter table snowlog_import.progress alter column next_step set default ''::text;
alter table snowlog_import.progress alter column video set default ''::text;
alter table snowlog_import.progress alter column feedback set default ''::text;
alter table snowlog_import.progress alter column updated_at set default now();
alter table snowlog_import.progress alter column assessment set default '{}'::jsonb;
alter table snowlog_import.trips alter column id set default gen_random_uuid();
alter table snowlog_import.trips alter column accommodation set default ''::text;
alter table snowlog_import.trips alter column transport set default ''::text;
alter table snowlog_import.trips alter column itinerary set default ''::text;
alter table snowlog_import.trips alter column todos set default '[]'::jsonb;
alter table snowlog_import.trips alter column invite_code set default upper(substr(replace((gen_random_uuid())::text, '-'::text, ''::text), 1, 16));
alter table snowlog_import.trips alter column updated_at set default now();
alter table snowlog_import.memberships alter column id set default gen_random_uuid();
alter table snowlog_import.memberships alter column goal set default ''::text;
alter table snowlog_import.journals alter column id set default gen_random_uuid();
alter table snowlog_import.journals alter column skill_ids set default '[]'::jsonb;
alter table snowlog_import.journals alter column notes set default ''::text;
alter table snowlog_import.journals alter column next_step set default ''::text;
alter table snowlog_import.journals alter column snow set default ''::text;
alter table snowlog_import.journals alter column mood set default '順利'::text;
alter table snowlog_import.journals alter column video set default ''::text;
alter table snowlog_import.journals alter column shared set default false;
alter table snowlog_import.journals alter column updated_at set default now();
alter table snowlog_import.journals alter column media set default '[]'::jsonb;
alter table snowlog_import.resources add constraint snowlog_resources_title_check CHECK (((length(title) >= 1) AND (length(title) <= 120)));
alter table snowlog_import.resources add constraint snowlog_resources_type_check CHECK ((type = ANY (ARRAY['教學'::text, '雪場'::text, '裝備'::text, '行前清單'::text, '其他'::text])));
alter table snowlog_import.profiles add constraint snowlog_profiles_focus_skills_check CHECK (((cardinality(focus_skills) <= 3) AND (focus_skills <@ ARRAY['one-foot'::text, 'heel-edge'::text, 'toe-edge'::text, 'falling-leaf'::text, 'j-turn'::text, 'linked-turns'::text, 'speed-control'::text, 'turn-rhythm'::text, 'carving'::text, 'switch'::text, 'short-turns'::text, 'variable-snow'::text, 'terrain'::text, 'ollie'::text, 'butter'::text, 'park'::text])));
alter table snowlog_import.profiles add constraint snowlog_profiles_goal_check CHECK ((length(goal) <= 4000));
alter table snowlog_import.profiles add constraint snowlog_profiles_name_check CHECK (((length(name) >= 1) AND (length(name) <= 120)));
alter table snowlog_import.profiles add constraint snowlog_profiles_stance_check CHECK ((stance = ANY (ARRAY['未確定'::text, 'Regular 左腳在前'::text, 'Goofy 右腳在前'::text])));
alter table snowlog_import.progress add constraint snowlog_progress_assessment_check CHECK (((jsonb_typeof(assessment) = 'object'::text) AND (octet_length((assessment)::text) <= 24000)));
alter table snowlog_import.progress add constraint snowlog_progress_check CHECK (((status <> 3) OR (length(TRIM(BOTH FROM conditions)) > 0)));
alter table snowlog_import.progress add constraint snowlog_progress_status_check CHECK (((status >= 0) AND (status <= 3)));
alter table snowlog_import.progress add constraint snowlog_progress_user_id_skill_id_key UNIQUE (user_id, skill_id);
alter table snowlog_import.trips add constraint snowlog_trips_check CHECK ((end_date >= start_date));
alter table snowlog_import.trips add constraint snowlog_trips_invite_code_key UNIQUE (invite_code);
alter table snowlog_import.trips add constraint snowlog_trips_resort_check CHECK (((length(resort) >= 1) AND (length(resort) <= 120)));
alter table snowlog_import.trips add constraint snowlog_trips_title_check CHECK (((length(title) >= 1) AND (length(title) <= 120)));
alter table snowlog_import.trips add constraint snowlog_trips_todos_check CHECK ((jsonb_typeof(todos) = 'array'::text));
alter table snowlog_import.memberships add constraint snowlog_memberships_goal_check CHECK ((length(goal) <= 4000));
alter table snowlog_import.memberships add constraint snowlog_memberships_trip_id_fkey FOREIGN KEY (trip_id) REFERENCES snowlog_import.trips(id) ON DELETE CASCADE;
alter table snowlog_import.memberships add constraint snowlog_memberships_trip_id_user_id_key UNIQUE (trip_id, user_id);
alter table snowlog_import.journals add constraint snowlog_journals_check CHECK (((NOT shared) OR (trip_id IS NOT NULL)));
alter table snowlog_import.journals add constraint snowlog_journals_media_check CHECK (((jsonb_typeof(media) = 'array'::text) AND (jsonb_array_length(media) <= 6)));
alter table snowlog_import.journals add constraint snowlog_journals_mood_check CHECK ((mood = ANY (ARRAY['順利'::text, '有突破'::text, '需要練習'::text, '自由滑行'::text])));
alter table snowlog_import.journals add constraint snowlog_journals_resort_check CHECK (((length(resort) >= 1) AND (length(resort) <= 120)));
alter table snowlog_import.journals add constraint snowlog_journals_skill_ids_check CHECK ((jsonb_typeof(skill_ids) = 'array'::text));
alter table snowlog_import.journals add constraint snowlog_journals_trip_id_fkey FOREIGN KEY (trip_id) REFERENCES snowlog_import.trips(id) ON DELETE SET NULL;
alter table snowlog_import.progress_history add constraint progress_history_previous_status_check CHECK (((previous_status >= 0) AND (previous_status <= 3)));
alter table snowlog_import.progress_history add constraint progress_history_snapshot_check CHECK ((jsonb_typeof(snapshot) = 'object'::text));
